import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, ActivityIndicator, Alert, KeyboardAvoidingView, Platform, ScrollView } from 'react-native';
import styled from 'styled-components/native';
import { colors, spacing, borderRadius } from '../../theme/tokens';
import api from '../../services/api';

const Container = styled.KeyboardAvoidingView`
  flex: 1;
  background-color: ${colors.white};
`;

const Content = styled.ScrollView.attrs({
  contentContainerStyle: { flexGrow: 1, padding: 24, justifyContent: 'center' }
})``;

const Header = styled.View`
  align-items: center;
  margin-bottom: ${spacing.xl + spacing.md}px;
`;

const LogoPlaceholder = styled.View`
  width: 120px;
  height: 120px;
  background-color: ${colors.surface};
  border-radius: ${borderRadius.lg}px;
  justify-content: center;
  align-items: center;
  margin-bottom: ${spacing.md}px;
`;

const Title = styled.Text`
  font-size: 28px;
  font-weight: bold;
  color: ${colors.secondary};
  text-align: center;
`;

const Subtitle = styled.Text`
  font-size: 16px;
  color: ${colors.textSecondary};
  text-align: center;
  margin-top: ${spacing.xs}px;
`;

const Form = styled.View`
  width: 100%;
`;

const Label = styled.Text`
  font-size: 14px;
  font-weight: 600;
  color: ${colors.text};
  margin-bottom: ${spacing.xs}px;
`;

const Input = styled.TextInput`
  height: 55px;
  background-color: ${colors.surface};
  border-radius: ${borderRadius.md}px;
  padding-horizontal: ${spacing.md}px;
  font-size: 16px;
  border-width: 1px;
  border-color: ${colors.border};
  margin-bottom: ${spacing.md}px;
`;

const Button = styled.TouchableOpacity`
  background-color: ${colors.primary};
  height: 55px;
  border-radius: ${borderRadius.md}px;
  justify-content: center;
  align-items: center;
  margin-top: ${spacing.md}px;
  opacity: ${props => props.disabled ? 0.6 : 1};
`;

const ButtonText = styled.Text`
  color: ${colors.white};
  font-size: 18px;
  font-weight: bold;
`;

const Footer = styled.View`
  flex-direction: row;
  justify-content: center;
  margin-top: ${spacing.xl}px;
`;

const FooterText = styled.Text`
  color: ${colors.textSecondary};
  font-size: 14px;
`;

const FooterLink = styled.TouchableOpacity``;

const FooterLinkText = styled.Text`
  color: ${colors.primary};
  font-size: 14px;
  font-weight: bold;
`;

const LoginScreen = () => {
  const [cpf, setCpf] = useState('');
  const [senha, setSenha] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async () => {
    if (!cpf || !senha) {
      Alert.alert('Erro', 'Por favor, preencha todos os campos.');
      return;
    }

    setLoading(true);
    try {
      const response = await api.passenger.login(cpf, senha);

      if (response.data.status === 'sucesso') {
        Alert.alert('Sucesso', `Bem-vindo, ${response.data.usuario.nome}!`);
        // Aqui você navegaria para a Home
      } else {
        Alert.alert('Erro', response.data.mensagem || 'Credenciais inválidas.');
      }
    } catch (error) {
      console.error(error);
      Alert.alert('Erro', 'Ocorreu um problema ao conectar com o servidor.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
      <Content showsVerticalScrollIndicator={false}>
        <Header>
          <LogoPlaceholder>
            <Text style={{ color: colors.textSecondary }}>LOGO</Text>
          </LogoPlaceholder>
          <Title>UbeZap</Title>
          <Subtitle>Mobilidade Urbana</Subtitle>
        </Header>

        <Form>
          <Label>CPF</Label>
          <Input 
            placeholder="000.000.000-00"
            placeholderTextColor={colors.textSecondary}
            keyboardType="numeric"
            value={cpf}
            onChangeText={setCpf}
          />

          <Label>Senha</Label>
          <Input 
            placeholder="••••••••"
            placeholderTextColor={colors.textSecondary}
            secureTextEntry
            value={senha}
            onChangeText={setSenha}
          />

          <Button activeOpacity={0.8} onPress={handleLogin} disabled={loading}>
            {loading ? (
              <ActivityIndicator color={colors.white} />
            ) : (
              <ButtonText>Entrar</ButtonText>
            )}
          </Button>
        </Form>

        <Footer>
          <FooterText>Ainda não tem conta? </FooterText>
          <FooterLink>
            <FooterLinkText>Cadastre-se</FooterLinkText>
          </FooterLink>
        </Footer>
      </Content>
    </Container>
  );
};

export default LoginScreen;
